mapper.select:
SELECT 
FROM t_yak_ops_datasource
WHERE id = #{id} AND project_code = #{projectCode}

SELECT d.id, d.name, d.note, d.type, d.user_id, d.project_code, d.connection_params, d.create_time, d.update_time, u.user_name AS user_name FROM t_yak_ops_datasource d JOIN t_yak_ops_user u ON d.user_id = u.id WHERE d.project_code = #{projectCode}
AND d.type = #{type}
AND d.name LIKE CONCAT('%', #{name}, '%')
ORDER BY d.update_time DESC, d.id DESC

SELECT CASE WHEN EXISTS (
    SELECT 1 FROM t_yak_ops_datasource
    WHERE project_code = #{projectCode} AND name = #{name}

        AND id != #{excludedId}

) THEN 1 ELSE 0 END

select

from t_yak_ops_datasource
where type=#{type}

    and id in
    (select datasource_id
    from t_yak_ops_relation_datasource_user
    where user_id=#{userId}
    union select id as datasource_id
    from t_yak_ops_datasource
    where user_id=#{userId}
    )

select ds.id, ds.name
from t_yak_ops_datasource ds, t_yak_ops_relation_datasource_user rel
where ds.id = rel.datasource_id AND rel.user_id = #{userId}

select id, name
from t_yak_ops_datasource
where user_id  <>  #{userId}
